// Pure source-owned data operations. No owner map, registration or admission exists here.
import { createHash } from 'node:crypto';
import { parseM4AssignmentRequest, type M4AssignmentRequest } from './m4-assignment-protocol';
import type * as Runtime from './m4-private-runtime-types';
import { captureM4PoolTarget } from './m4-pool-posture';
type Profile = 'ops' | 'legacy-admin' | 'legacy-agent' | 'staff';
export type M4LocalAssignmentOwner = {
  closed(): boolean;
  active(): number;
  refused(): boolean;
  captures: Array<
    Readonly<{
      ordinal: number;
      operationId: string;
      requestDigest: string;
      responseDigest: string | null;
      profile: Profile;
      receiver: 'posture-checked-owned-data-drizzle';
      verifier: 'owned-current-store-identity-drizzle';
      configurationIdentityChecked: true;
      capturedAfterPosture: true;
    }>
  >;
};

export function captureM4PrivateRuntimeConfiguration(
  configuration: Runtime.M4PrivateRuntimeConfiguration,
  loopbackQualification: boolean,
  notificationConfiguration?: Readonly<{
    notificationDatabaseURL: string;
    notificationDatabaseDeadlineMs: number;
  }>
) {
  // Snapshot only primitive configuration. No caller factory, pool, callback, principal DTO,
  // arbitrary PostgreSQL option, or per-request transport flag enters this construction.
  const { identityDatabaseURL, dataDatabaseURL, issuerBaseURL, issuerSecret, operationDeadlineMs } =
    configuration;
  if (
    !Number.isSafeInteger(operationDeadlineMs) ||
    operationDeadlineMs < 1 ||
    operationDeadlineMs > 2_147_483_647
  )
    throw new Error('Explicit private M4 operation deadline required');
  try {
    if (
      typeof issuerBaseURL !== 'string' ||
      typeof issuerSecret !== 'string' ||
      issuerSecret.length < 32
    )
      throw new Error();
    const issuer = new URL(issuerBaseURL);
    if (
      !['http:', 'https:'].includes(issuer.protocol) ||
      issuer.username ||
      issuer.password ||
      issuer.search ||
      issuer.hash
    )
      throw new Error();
  } catch {
    throw new Error('Invalid private M4 issuer configuration');
  }
  const identityTarget = captureM4PoolTarget(identityDatabaseURL, loopbackQualification);
  const dataTarget = captureM4PoolTarget(dataDatabaseURL, loopbackQualification);
  if (
    identityTarget.login === dataTarget.login ||
    identityTarget.serverKey !== dataTarget.serverKey
  )
    throw new Error('Private M4 requires distinct purpose logins on the same database endpoint');
  const notificationDatabaseDeadlineMs = notificationConfiguration?.notificationDatabaseDeadlineMs;
  const notificationTarget = notificationConfiguration
    ? captureM4PoolTarget(notificationConfiguration.notificationDatabaseURL, loopbackQualification)
    : undefined;
  if (
    notificationTarget &&
    (!Number.isSafeInteger(notificationDatabaseDeadlineMs) ||
      notificationDatabaseDeadlineMs! < 1 ||
      notificationDatabaseDeadlineMs! > 2_147_483_647 ||
      notificationTarget.login === identityTarget.login ||
      notificationTarget.login === dataTarget.login ||
      notificationTarget.serverKey !== dataTarget.serverKey)
  )
    throw new Error(
      'Private assignment notification requires distinct purpose login and explicit DB deadline'
    );
  const captured = Object.freeze({
    issuerBaseURL,
    issuerSecret,
    operationDeadlineMs,
    notificationDatabaseDeadlineMs,
  });
  return { captured, identityTarget, dataTarget, notificationTarget };
}

export function readM4ClosedAssignmentContexts(owner: M4LocalAssignmentOwner | undefined) {
  if (!owner || !owner.closed() || owner.active() !== 0 || owner.refused())
    throw new Error('M4 actual closed local owner required');
  return Object.freeze({
    version: 1,
    localQualificationOnly: true,
    rows: Object.freeze([...owner.captures]),
  });
}

// Strict observations are separate from local receipts and never grant admission.
export function readM4StrictAssignmentContexts(owner: M4LocalAssignmentOwner | undefined) {
  if (!owner || !owner.closed() || owner.active() !== 0 || owner.refused())
    throw new Error('M4 actual closed drained strict owner required');
  return Object.freeze({
    version: 1,
    localQualificationOnly: false,
    constructorName: 'createM4PrivateAssignmentRuntime' as const,
    loopbackQualification: false,
    rows: Object.freeze([...owner.captures]),
  });
}

export function observeM4AssignmentInvocation(
  profile: Profile,
  configuration: Readonly<{ database: unknown; verifySession: unknown }>,
  database: unknown,
  verifySession: unknown,
  identity: unknown,
  data: unknown,
  ordinal: number
): Omit<
  M4LocalAssignmentOwner['captures'][number],
  'operationId' | 'requestDigest' | 'responseDigest'
> {
  if (
    !Object.isFrozen(configuration) ||
    configuration.database !== database ||
    configuration.verifySession !== verifySession ||
    !database ||
    !verifySession ||
    !identity ||
    !data ||
    identity === data
  )
    throw new Error('M4 captured assignment configuration changed');
  return Object.freeze({
    ordinal,
    profile,
    receiver: 'posture-checked-owned-data-drizzle',
    verifier: 'owned-current-store-identity-drizzle',
    configurationIdentityChecked: true,
    capturedAfterPosture: true,
  });
}

export type M4LocalAssignmentCaptureState = {
  budget?: { used: number; refused: boolean };
  refused: boolean;
  rows: M4LocalAssignmentOwner['captures'];
};
// The returned closure lives only in the current owned work; state retains scalar rows only.
export function bindM4AssignmentInvocation(
  state: M4LocalAssignmentCaptureState,
  profile: Profile,
  configuration: Readonly<{ database: unknown; verifySession: unknown }>,
  database: unknown,
  verifySession: unknown,
  identity: unknown,
  data: unknown,
  request: M4AssignmentRequest
) {
  const budget = state.budget;
  if (!budget) return <T>(result: T): T => result;
  try {
    if (state.rows.length >= 128 || budget.refused || budget.used >= 2048) {
      budget.refused = true;
      throw new Error('M4 local assignment context bound');
    }
    const parsed = parseM4AssignmentRequest(JSON.stringify(request));
    if (!parsed || JSON.stringify(parsed) !== JSON.stringify(request))
      throw new Error('M4 captured request changed');
    const row = Object.freeze({
      ...observeM4AssignmentInvocation(
        profile,
        configuration,
        database,
        verifySession,
        identity,
        data,
        state.rows.length + 1
      ),
      operationId: parsed.operationId,
      requestDigest: createHash('sha256').update(JSON.stringify(parsed)).digest('hex'),
      responseDigest: null,
    });
    const index = state.rows.length;
    budget.used++;
    state.rows.push(row);
    let completed = false;
    // Retain scalar bookkeeping only; raw DB/verifier/pool references leave at this boundary.
    return <T>(result: T): T => {
      try {
        if (completed || state.rows[index] !== row)
          throw new Error('M4 invocation settlement changed');
        const serialized = JSON.stringify(result);
        if (serialized === undefined) throw new Error('M4 controller return missing');
        completed = true;
        state.rows[index] = Object.freeze({
          ...row,
          responseDigest: createHash('sha256').update(serialized).digest('hex'),
        });
        return result;
      } catch {
        state.refused = true;
        throw new Error('M4 captured assignment settlement changed');
      }
    };
  } catch {
    state.refused = true;
    throw new Error('M4 captured assignment configuration changed');
  }
}

sources.posture:
import type postgres from 'postgres';
import { checkServerIdentity, type PeerCertificate } from 'node:tls';

export type M4PoolTarget = Readonly<{
  url: string;
  login: string;
  database: string;
  serverKey: string;
}>;

// Called only while constructing the private bootstrap, never from an operation payload.
export function captureM4PoolTarget(value: unknown, loopbackQualification: boolean): M4PoolTarget {
  try {
    if (typeof value !== 'string' || value.length > 8192) throw new Error();
    const url = new URL(value);
    const login = decodeURIComponent(url.username);
    const password = decodeURIComponent(url.password);
    const database = decodeURIComponent(url.pathname.slice(1));
    const host = url.hostname.toLowerCase();
    if (
      !['postgres:', 'postgresql:'].includes(url.protocol) ||
      url.search ||
      url.hash ||
      !login ||
      !password ||
      !database ||
      /[\u0000-\u001f\u007f]/u.test(login + password + database) ||
      url.pathname.slice(1).includes('/') ||
      // The pinned driver's URL parser retains encoded database names and splits IPv6 hosts.
      // These endpoint forms require separate qualification rather than silent reinterpretation.
      url.pathname.slice(1) !== database ||
      !/^[a-z0-9][a-z0-9.-]*$/u.test(host) ||
      (loopbackQualification && host !== '127.0.0.1' && host !== 'localhost')
    )
      throw new Error();
    // postgres.js otherwise consults PGPORT when the serialized URL omits its port.
    url.port ||= '5432';
    return Object.freeze({
      url: url.href,
      login,
      database,
      serverKey: JSON.stringify([host, url.port || '5432', database]),
    });
  } catch {
    // Never include a credential-bearing URL or the URL parser's original error.
    throw new Error('Invalid private M4 database configuration');
  }
}

// Bind the standard Node certificate identity check to the captured endpoint, not a
// hostname inferred from the driver's already connected socket. No request supplies a callback.
export function captureM4DatabaseTls(target: M4PoolTarget) {
  const expectedHostname = new URL(target.url).hostname;
  return Object.freeze({
    rejectUnauthorized: true,
    checkServerIdentity(_driverHostname: string, certificate: PeerCertificate) {
      return checkServerIdentity(expectedHostname, certificate);
    },
  });
}

// These installed-driver fallbacks select unqualified behavior even with a complete URL.
// Check again immediately before constructing pools: process.env is mutable in this process.
export function assertM4DriverEnvironment(): void {
  const options = [
    'SSLNEGOTIATION',
    'IDLE_TIMEOUT',
    'MAX_LIFETIME',
    'MAX_PIPELINE',
    'BACKOFF',
    'KEEP_ALIVE',
    'PREPARE',
    'DEBUG',
    'FETCH_TYPES',
    'PUBLICATIONS',
    'TARGET_SESSION_ATTRS',
    'TARGETSESSIONATTRS',
  ];
  if (options.some(option => Boolean(process.env[`PG${option}`])))
    throw new Error('Unsupported private M4 driver environment');
}

// Every restriction is enforced in PostgreSQL before row decoding. No boolean returned by
// a potentially incorrect driver parser can turn a forbidden role into a passing gate.
export async function assertM4PoolPosture(
  client: postgres.Sql,
  target: M4PoolTarget
): Promise<void> {
  const rows = await client<{ gate: number }[]>`
    select 1 OPERATOR(pg_catalog./) case when
      CAST(checked.rolname AS pg_catalog.text) OPERATOR(pg_catalog.=) CAST(${target.login} AS pg_catalog.text)
      and session_user OPERATOR(pg_catalog.=) current_user
      and pg_catalog.current_setting('client_connection_check_interval') OPERATOR(pg_catalog.=) '100ms'
      and CAST(pg_catalog.current_database() AS pg_catalog.text) OPERATOR(pg_catalog.=) CAST(${target.database} AS pg_catalog.text)
      and checked.rolcanlogin and not checked.rolsuper and not checked.rolbypassrls
      and not checked.rolcreatedb and not checked.rolcreaterole
      and not checked.rolreplication and not checked.rolinherit
      and not exists (
        select 1 from pg_catalog.pg_auth_members as membership
        where membership.member OPERATOR(pg_catalog.=) checked.oid
      )
      and not exists (
        select 1 from pg_catalog.pg_class as relation
        where relation.relowner OPERATOR(pg_catalog.=) checked.oid
      )
      and not exists (
        select 1 from pg_catalog.pg_proc as routine
        join pg_catalog.pg_namespace as namespace
          on namespace.oid OPERATOR(pg_catalog.=) routine.pronamespace
        where routine.prosecdef
          and namespace.nspname OPERATOR(pg_catalog.<>) CAST('pg_catalog' AS pg_catalog.name)
          and namespace.nspname OPERATOR(pg_catalog.<>) CAST('information_schema' AS pg_catalog.name)
          and pg_catalog.has_function_privilege(checked.oid, routine.oid, 'EXECUTE')
      )
      then 1 else 0 end as gate
    from pg_catalog.pg_roles as checked
    where checked.rolname OPERATOR(pg_catalog.=) session_user
    limit 1
  `;
  if (rows.length !== 1 || rows[0]?.gate !== 1) throw new Error('Private M4 pool posture denied');
}

sources.runtimeTypes:
import type { Profile } from './m4-assignment-controller-types';
import type { M4OpsResponse } from './m4-ops-controller';
import type { M4Response, LegacyResult, StaffResult } from './m4-assignment-wire';

export type M4PrivateRuntimeConfiguration = Readonly<{
  identityDatabaseURL: string;
  dataDatabaseURL: string;
  issuerBaseURL: string;
  issuerSecret: string;
  operationDeadlineMs: number;
}>;
export type M4PrivateRuntime = Readonly<{
  execute(cookie: unknown, serialized: unknown): Promise<M4OpsResponse>;
  close(): Promise<void>;
}>;
export type M4PrivateAssignmentRuntimeConfiguration = M4PrivateRuntimeConfiguration &
  Readonly<{
    notificationDatabaseURL: string;
    notificationDatabaseDeadlineMs: number;
  }>;
